@namespace sv_5feca5c5f7484224bcf05c5d7d0b9e4c.Components.JobApplication

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Entry.Company" @onchange="e => Update(e, nameof(Entry.Company))" class="form-control" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title" @onchange="e => Update(e, nameof(Entry.Title))" class="form-control" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => UpdateStartDate(e)" class="form-control" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateEndDate(e)"
                   class="form-control" disabled="@_isCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@_isCurrent" @onchange="ToggleCurrent" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="e => Update(e, nameof(Entry.Description))" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }

    private bool _isCurrent;

    protected override void OnParametersSet()
    {
        _isCurrent = Entry.EndDate is null && Entry.StartDate != default;
    }

    private async Task Update(ChangeEventArgs e, string field)
    {
        var value = e.Value?.ToString() ?? "";
        var updated = field switch
        {
            nameof(Entry.Company) => Entry with { Company = value },
            nameof(Entry.Title) => Entry with { Title = value },
            nameof(Entry.Description) => Entry with { Description = value },
            _ => Entry
        };
        await OnChanged.InvokeAsync(updated);
    }

    private async Task UpdateStartDate(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
        {
            await OnChanged.InvokeAsync(Entry with { StartDate = date });
        }
    }

    private async Task UpdateEndDate(ChangeEventArgs e)
    {
        DateTime? date = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null;
        await OnChanged.InvokeAsync(Entry with { EndDate = date });
    }

    private async Task ToggleCurrent(ChangeEventArgs e)
    {
        _isCurrent = (bool)(e.Value ?? false);
        await OnChanged.InvokeAsync(Entry with { EndDate = _isCurrent ? null : DateTime.Today });
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }
}

