{"file_text": "@page "/apply"
@using sv_5feca5c5f7484224bcf05c5d7d0b9e4c.Components.JobApplication
@using sv_5feca5c5f7484224bcf05c5d7d0b9e4c.Models
@using sv_5feca5c5f7484224bcf05c5d7d0b9e4c.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="job-application">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName"
                              Email="@_email"
                              Phone="@_phone"
                              Address="@_address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@(new PersonalInfoStep.PersonalInfoResult(_fullName, _email, _phone, _address))"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        OnEdit="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private HashSet<int> _completedSteps = new();

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> _workEntries = new();

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> _references = new();

    // Step 4 state
    private string _coverLetter = "";

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        _fullName = result.FullName;
        _email = result.Email;
        _phone = result.Phone;
        _address = result.Address;
        _completedSteps.Add(0);
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        _workEntries = entries;
        _completedSteps.Add(1);
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> references)
    {
        _references = references;
        _completedSteps.Add(2);
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _completedSteps.Add(3);
        _currentStep = 4;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
        }
    }

    private async Task<int> SubmitApplication()
    {
        var workHistory = new WorkHistory(
            _workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description
            )).ToList()
        );

        var references = _references.Select(r => new Reference(
            r.Name, r.Relationship, r.Email, r.Phone
        )).ToList();

        var personalInfo = new PersonalInfo(_fullName, _email, _phone, _address);

        var application = new JobApplication(personalInfo, workHistory, references, _coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}
