toolArgs.file_text:
.job-application {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.job-application h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    min-width: 80px;
    transition: opacity 0.2s;
}

.step-indicator .step:disabled {
    cursor: default;
}

.step-indicator .step .step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.25rem;
    border: 2px solid #ccc;
    background: white;
    color: #999;
}

.step-indicator .step.current .step-number {
    border-color: #4361ee;
    background: #4361ee;
    color: white;
}

.step-indicator .step.completed .step-number {
    border-color: #2ec4b6;
    background: #2ec4b6;
    color: white;
}

.step-indicator .step .step-label {
    font-size: 0.75rem;
    color: #999;
    text-align: center;
}

.step-indicator .step.current .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-indicator .step.completed .step-label {
    color: #2ec4b6;
}

.step-connector {
    width: 30px;
    height: 2px;
    background: #ddd;
    margin: 0 0.25rem;
    align-self: center;
    margin-bottom: 1rem;
}

.step-connector.completed {
    background: #2ec4b6;
}

/* Step Content */
.step-content {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 0.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #666;
    margin-bottom: 1.5rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    color: #333;
    font-size: 0.9rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 1rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #555;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.btn {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background-color 0.2s, opacity 0.2s;
    font-weight: 500;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #4361ee;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #3a56d4;
}

.btn-outline {
    background: white;
    color: #4361ee;
    border: 1px solid #4361ee;
}

.btn-outline:hover:not(:disabled) {
    background: #f0f3ff;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    border: 1px solid #ddd;
}

.btn-secondary:hover:not(:disabled) {
    background: #e0e0e0;
}

.btn-danger {
    background: #e63946;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background: #d62839;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #3a56d4;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

/* Step Actions */
.step-actions {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

/* Validation */
.validation-summary {
    background: #fff3f3;
    border: 1px solid #ffcdd2;
    color: #c62828;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
    font-size: 0.9rem;
}

.field-error {
    color: #c62828;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    color: #444;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
    font-family: inherit;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #c62828;
    font-weight: bold;
}

/* Review Step */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #333;
}

.review-data {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #666;
    font-size: 0.9rem;
}

.review-data dd {
    margin: 0;
    color: #333;
}

.review-work-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
}

.review-work-entry:last-child {
    border-bottom: none;
}

.date-range {
    font-size: 0.85rem;
    color: #666;
}

.work-description {
    margin: 0.25rem 0 0;
    color: #555;
    font-size: 0.9rem;
}

.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
}

.review-reference:last-child {
    border-bottom: none;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f8f8f8;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    line-height: 1.5;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
}

.submission-confirmation h3 {
    color: #2ec4b6;
    font-size: 1.5rem;
}

.submission-confirmation p {
    color: #555;
    font-size: 1.1rem;
}

/* Responsive */
@media (max-width: 600px) {
    .form-row {
        grid-template-columns: 1fr;
    }

    .step-indicator {
        gap: 0.1rem;
    }

    .step-indicator .step {
        min-width: 60px;
        padding: 0.25rem;
    }

    .step-connector {
        width: 15px;
    }
}

